package sv.edu.ues.vl23003.saldo.ui.splash; import android.app.Activity; import android.os.Bundle; import android.content.Intent; import sv.edu.ues.vl23003.saldo.R; import sv.edu.ues.vl23003.saldo.ui.auth.LoginActivity; public class SplashActivity extends Activity {protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_splash); new android.os.Handler().postDelayed(()->{startActivity(new Intent(this,LoginActivity.class));finish();},700);}}
